"""Independent finite-state verification of a two-letter quotient construction.
Python 3 stdlib only; exhaustive reachable monoid and Myhill-Nerode refinement.
"""
from collections import deque
from math import factorial


def state_machine(k, d, m):
    # State zero-based; S_k generated by the k-cycle and (0 1).
    n_states = k * d
    a = [((i+1) % k)*d + (j+1) % d for i in range(k) for j in range(d)]
    b = [(1-i if i < 2 else i)*d+j for i in range(k) for j in range(d)]
    finals_b = {i*d+j for i in range(k) for j in range(d-1) if i == k-1}
    am = [(i+1) % k for i in range(k)]
    bm = [(1-i if i < 2 else i) for i in range(k)]
    fa = set(range(m))
    return (a,b,finals_b,am,bm,fa)


def closure_monoid_maps(generators):
    # Independent semigroup enumeration; the identity is the empty word.
    size = len(generators[0])
    eye = tuple(range(size))
    seen = {eye}
    todo = deque([eye])
    while todo:
        p = todo.popleft()
        for g in generators:
            t = tuple(g[x] for x in p)
            if t not in seen:
                seen.add(t)
                todo.append(t)
    return seen


def minimal_partition(transitions, finals):
    # Moore refinement; uses all states, checked independently for reachability.
    N = len(transitions[0]); finalset = set(finals)
    lab = [int(i in finalset) for i in range(N)]
    while True:
        key = [(lab[i],*(lab[t[i]] for t in transitions)) for i in range(N)]
        ids = {t:j for j,t in enumerate(sorted(set(key)))}
        next_lab = [ids[t] for t in key]
        if len(set(next_lab)) == len(set(lab)):
            return len(set(next_lab)), len({next_lab[i] for i in finalset})
        lab = next_lab


def verify():
    ncases = 0
    max_monoid = 0
    for k in range(2,7):
        for d in range(2,6):
            a,b,fb,am,bm,_ = state_machine(k,d,1)
            S = closure_monoid_maps([a,b])
            expect = factorial(k)*d
            assert len(S) == expect, (k,d,len(S),expect)
            max_monoid = max(max_monoid,len(S))
            assert len({p[(k-1)*d] for p in S}) == k*d
            assert minimal_partition([a,b],fb) == (k*d,d-1), (k,d,'B minimal')
            # Quotient via independently enumerating all possible group actions
            # Accepted transformations of B have final B state from initial (k-1,0).
            accepted_perms = set()
            for p in S:
                if p[(k-1)*d] in fb:
                    accepted_perms.add(tuple(p[i*d]//d for i in range(k)))
            stabilizer = {p for p in accepted_perms if p[k-1] == k-1}
            assert len(accepted_perms)==factorial(k-1)==len(stabilizer)
            for m in range(1,k):
                fa=set(range(m))
                final_q={i for i in range(k) if any(p[i] in fa for p in accepted_perms)}
                assert final_q==set(range(k-1)),(k,d,m,final_q)
                assert minimal_partition([am,bm],fa)==(k,m)
                assert minimal_partition([am,bm],final_q)==(k,k-1)
                ncases+=1
    print('COMPLETE CHECKS PASSED')
    print('alphabet_size=2; k=2..6; d=2..5; m=1..k-1')
    print(f'triples_tested={ncases}')
    print('group sizes fully enumerated: factorial(k)*d for 20 (k,d) pairs')
    print(f'maximum enumerated transformation group size={max_monoid}')
    print('Each B minimal with d-1 finals; A minimal with m finals; quotient minimal with k-1 finals.')
    print('No finite check is offered as a proof for arbitrary parameters.')


if __name__=='__main__':verify()
